mapper.sql:
FROM todos t
JOIN plans p ON p.id = t.plan_id
WHERE t.plan_id = #{planId}
  AND 

  AND t.title ILIKE '%' || #{queryPattern} || '%' ESCAPE '\'


  AND t.status = #{status}


  AND t.priority = #{priority}


  AND EXISTS (
      SELECT 1
      FROM todo_tags tt
      JOIN tags g ON g.id = tt.tag_id
      WHERE tt.todo_id = t.id
        AND tt.tag_id = #{tagId}
        AND g.user_id = #{userId}
        AND g.deleted_at IS NULL
  )



      AND 


      AND 


      AND t.due_date > #{today}


      AND t.due_date IS NULL

mapper.select:
SELECT t.plan_id
FROM todos t
JOIN plans p ON p.id = t.plan_id
WHERE t.id = #{todoId}
  AND p.deleted_at IS NULL
  AND p.user_id = #{userId}

SELECT COALESCE(MAX(r.revision_no), 0) + 1 AS next_revision_no
FROM todo_revisions r
WHERE r.todo_id = #{todoId}
